// Builds the request for the local LLM. One item = one customer message.
const CATEGORIES = {
  order_status: 'where is my order, delivery date, change address, cancel an order',
  payment: 'paid but not confirmed, charged twice, payment methods, payment page errors',
  product_question: 'availability, size, price, specs, warranty, wholesale',
  complaint: 'damaged, broken, wrong item, faulty product, rude staff',
  spam: 'scams, prize links, ads, phishing, follower selling',
  other: 'opening hours, shop location, thanks, jobs, anything else',
};
const text = String($json.text ?? '').trim();
// Amharic letters live in the Ethiopic Unicode block (U+1200-U+137F).
const lang = /[\u1200-\u137F]/.test(text) ? 'am' : 'en';

const system = [
  'You triage customer messages for a small online shop in Ethiopia.',
  'Messages may be English, Amharic (Ethiopic script), or Amharic typed in Latin letters.',
  'Pick exactly one category:',
  ...Object.entries(CATEGORIES).map(([k, v]) => '- ' + k + ': ' + v),
  'Urgency: high = money lost, damaged/wrong item, angry or repeat message, or a deadline today;',
  'normal = needs action soon (order changes, payment checks); low = simple questions, thanks, spam.',
  'confidence = how sure you are, 0 to 1.',
  'summary = one short English sentence.',
  'reply_draft = a short polite reply in the SAME language and script as the customer.',
  'Never promise refunds, prices or delivery dates in reply_draft.',
  'Answer with JSON only.',
].join('\n');

// Ollama "structured outputs": the model must fill this JSON schema.
const schema = {
  type: 'object',
  properties: {
    category: { type: 'string', enum: Object.keys(CATEGORIES) },
    urgency: { type: 'string', enum: ['high', 'normal', 'low'] },
    confidence: { type: 'number' },
    summary: { type: 'string' },
    reply_draft: { type: 'string' },
  },
  required: ['category', 'urgency', 'confidence', 'summary', 'reply_draft'],
};

return {
  json: {
    ...$json,
    text,
    lang,
    llm_request: {
      model: $json.model,
      stream: false,
      format: schema,
      options: { temperature: 0 },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: text },
      ],
    },
  },
};

// Guardrail: never trust the model's answer blindly.
// Anything broken or unsure goes to a human instead of to the customer.
const ALLOWED = ['order_status', 'payment', 'product_question', 'complaint', 'spam', 'other'];
const URGENCY = ['high', 'normal', 'low'];

const input = $('Build prompt').item.json;           // the original message
const { llm_request, ollama_url, min_confidence, ...record } = input;
// Fields named cfg_* are settings from the calling workflow, not message data.
for (const k of Object.keys(record)) if (k.startsWith('cfg_')) delete record[k];

let problem = null;
let out = {};
if ($json.error) {
  problem = 'llm_unreachable';                         // HTTP error after retries
} else {
  try { out = JSON.parse($json.message?.content ?? ''); }
  catch { problem = 'invalid_json'; }
  if (!problem && !ALLOWED.includes(out.category)) problem = 'unknown_category';
  if (!problem && !URGENCY.includes(out.urgency)) problem = 'unknown_urgency';
}

const confidence = Number(out.confidence);
const lowConfidence = !problem && !(confidence >= min_confidence);

let route;
if (problem || lowConfidence) route = 'needs_human';
else if (out.category === 'spam') route = 'spam';
else if (out.urgency === 'high') route = 'urgent';
else route = 'auto';

return {
  json: {
    ...record,
    category: problem ? 'needs_human' : out.category,
    urgency: problem ? 'high' : out.urgency,
    confidence: Number.isFinite(confidence) ? confidence : null,
    summary: out.summary ?? '',
    reply_draft: problem ? '' : (out.reply_draft ?? ''),
    route,
    problem: problem ?? (lowConfidence ? 'low_confidence' : null),
    triaged_at: new Date().toISOString(),
  },
};
